#pragma once
#include <Arduino.h>
#include <string.h>

// Compressed 128x64 1-bit Mochi animations for SH1106/SSD1306-style OLEDs.
// Settings: fit scale, threshold 128, horizontal scan, MSB first, no invert/flip/rotation.
// Decoder output is 1024 bytes per frame: 128 * 64 / 8.

constexpr uint16_t MOCHI_WIDTH = 128;
constexpr uint16_t MOCHI_HEIGHT = 64;
constexpr uint16_t MOCHI_BYTES_PER_FRAME = 1024;

enum MochiFrameMode : uint8_t { MOCHI_FRAME_RLE = 0, MOCHI_FRAME_PATCH = 1 };

struct MochiAnimation {
  const char* name;
  const uint8_t* data;
  const uint32_t* offsets;
  const uint16_t* durations;
  const uint8_t* modes;
  uint16_t frameCount;
  uint16_t width;
  uint16_t height;
  uint16_t bytesPerFrame;
};

static inline uint8_t mochiRead8(const uint8_t* p) { return pgm_read_byte(p); }
static inline uint16_t mochiRead16(const uint16_t* p) { return pgm_read_word(p); }
static inline uint32_t mochiRead32(const uint32_t* p) { return pgm_read_dword(p); }

static void mochiDecodeRle(const uint8_t* src, uint16_t len, uint8_t* out) {
  uint16_t ip = 0, op = 0;
  while (ip < len && op < MOCHI_BYTES_PER_FRAME) {
    uint8_t token = mochiRead8(src + ip++);
    uint16_t count = (token & 0x7F) + 1;
    if (token & 0x80) {
      uint8_t value = mochiRead8(src + ip++);
      while (count-- && op < MOCHI_BYTES_PER_FRAME) out[op++] = value;
    } else {
      while (count-- && ip < len && op < MOCHI_BYTES_PER_FRAME) out[op++] = mochiRead8(src + ip++);
    }
  }
}

static void mochiApplyPatch(const uint8_t* src, uint16_t len, uint8_t* out) {
  uint16_t ip = 0;
  while (ip + 3 <= len) {
    uint16_t offset = mochiRead8(src + ip) | (uint16_t(mochiRead8(src + ip + 1)) << 8);
    ip += 2;
    uint16_t count = uint16_t(mochiRead8(src + ip++)) + 1;
    for (uint16_t i = 0; i < count && ip < len && offset + i < MOCHI_BYTES_PER_FRAME; ++i) {
      out[offset + i] = mochiRead8(src + ip++);
    }
  }
}

static bool mochiDecodeFrame(const MochiAnimation& animation, uint16_t frameIndex, uint8_t* out) {
  if (frameIndex >= animation.frameCount || out == nullptr) return false;
  memset(out, 0, MOCHI_BYTES_PER_FRAME);
  for (uint16_t frame = 0; frame <= frameIndex; ++frame) {
    uint32_t start = mochiRead32(animation.offsets + frame);
    uint32_t end = mochiRead32(animation.offsets + frame + 1);
    uint8_t mode = mochiRead8(animation.modes + frame);
    const uint8_t* chunk = animation.data + start;
    uint16_t len = uint16_t(end - start);
    if (mode == MOCHI_FRAME_RLE) mochiDecodeRle(chunk, len, out);
    else mochiApplyPatch(chunk, len, out);
  }
  return true;
}

static uint16_t mochiFrameDuration(const MochiAnimation& animation, uint16_t frameIndex) {
  if (frameIndex >= animation.frameCount) return 100;
  return mochiRead16(animation.durations + frameIndex);
}

